#!/usr/bin/env node
/**
 * Rate limiter simulator
 */

import { readFileSync } from 'fs';

// Helper function to synchronously read stdin
function readStdin() {
  return readFileSync(0, 'utf-8');
}

// Validate that a string only contains allowed characters
function isValidIdentifier(str) {
  return /^[A-Za-z0-9_./:_-]+$/.test(str);
}

// Parse unsigned integer with validation
function parseUint(str, field, minimum, lineNum) {
  if (!/^\d+$/.test(str)) {
    throw new Error(`error: line ${lineNum}: ${field} must be an integer of at least ${minimum}`);
  }

  // Check for leading zeros (only "0" is allowed as 0)
  if (str.length > 1 && str[0] === '0') {
    throw new Error(`error: line ${lineNum}: ${field} must be an integer of at least ${minimum}`);
  }

  const value = parseInt(str, 10);
  if (value < minimum) {
    throw new Error(`error: line ${lineNum}: ${field} must be an integer of at least ${minimum}`);
  }

  return value;
}

// Token Bucket implementation
class BucketState {
  constructor(capacity, refill, per) {
    this.capacity = capacity;
    this.refill = refill;
    this.per = per;
    this.tokens = capacity; // Start full
    this.lastTick = 0;
  }

  advance(tick) {
    const ticksPassed = tick - this.lastTick;
    // Add refill tokens per 'per' ticks, with exact fractional arithmetic
    this.tokens += (this.refill * ticksPassed) / this.per;
    if (this.tokens > this.capacity) {
      this.tokens = this.capacity;
    }
    this.lastTick = tick;
  }

  check() {
    return this.tokens >= 1;
  }

  record() {
    this.tokens -= 1;
  }
}

// Sliding Window implementation
class WindowState {
  constructor(limit, span) {
    this.limit = limit;
    this.span = span;
    this.ticks = [];
  }

  advance(tick) {
    // Forget ticks at or before tick - span
    const cutoff = tick - this.span;
    this.ticks = this.ticks.filter(t => t > cutoff);
  }

  check() {
    return this.ticks.length < this.limit;
  }

  record(tick) {
    this.ticks.push(tick);
  }
}

// Main parsing function
function parse(input) {
  const lines = input.split('\n');
  const policies = {}; // name -> policy definition
  const routes = []; // array of { prefix, policyNames }
  const events = []; // array of { tick, key }
  const seenPrefixes = new Set();

  let firstEventLine = -1;
  let lastTick = -1;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    let line = lines[i].trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      continue;
    }

    // Split on whitespace
    const parts = line.split(/\s+/);
    const directive = parts[0];

    if (directive === 'bucket') {
      if (firstEventLine !== -1) {
        throw new Error(`error: line ${lineNum}: declarations must come before the first event`);
      }

      if (parts.length !== 5) {
        throw new Error(`error: line ${lineNum}: expected bucket <name> <capacity> <refill> <per>`);
      }

      const name = parts[1];
      const capacity = parseUint(parts[2], 'capacity', 1, lineNum);
      const refill = parseUint(parts[3], 'refill', 0, lineNum);
      const per = parseUint(parts[4], 'per', 1, lineNum);

      if (!isValidIdentifier(name)) {
        throw new Error(`error: line ${lineNum}: invalid policy name ${name}`);
      }

      if (policies.hasOwnProperty(name)) {
        throw new Error(`error: line ${lineNum}: policy ${name} is declared twice`);
      }

      policies[name] = {
        type: 'bucket',
        capacity,
        refill,
        per
      };
    } else if (directive === 'window') {
      if (firstEventLine !== -1) {
        throw new Error(`error: line ${lineNum}: declarations must come before the first event`);
      }

      if (parts.length !== 4) {
        throw new Error(`error: line ${lineNum}: expected window <name> <limit> <span>`);
      }

      const name = parts[1];
      const limit = parseUint(parts[2], 'limit', 0, lineNum);
      const span = parseUint(parts[3], 'span', 1, lineNum);

      if (!isValidIdentifier(name)) {
        throw new Error(`error: line ${lineNum}: invalid policy name ${name}`);
      }

      if (policies.hasOwnProperty(name)) {
        throw new Error(`error: line ${lineNum}: policy ${name} is declared twice`);
      }

      policies[name] = {
        type: 'window',
        limit,
        span
      };
    } else if (directive === 'route') {
      if (firstEventLine !== -1) {
        throw new Error(`error: line ${lineNum}: declarations must come before the first event`);
      }

      if (parts.length < 3) {
        throw new Error(`error: line ${lineNum}: expected route <prefix> <policy>...`);
      }

      const prefix = parts[1];
      const policyNames = parts.slice(2);

      if (!isValidIdentifier(prefix)) {
        throw new Error(`error: line ${lineNum}: invalid route prefix ${prefix}`);
      }

      if (seenPrefixes.has(prefix)) {
        throw new Error(`error: line ${lineNum}: prefix ${prefix} is routed twice`);
      }
      seenPrefixes.add(prefix);

      for (const policyName of policyNames) {
        if (!policies.hasOwnProperty(policyName)) {
          throw new Error(`error: line ${lineNum}: unknown policy ${policyName}`);
        }
      }

      routes.push({ prefix, policyNames });
    } else if (directive === 'event') {
      if (firstEventLine === -1) {
        firstEventLine = lineNum;
      }

      if (parts.length !== 3) {
        throw new Error(`error: line ${lineNum}: expected event <tick> <key>`);
      }

      const tick = parseUint(parts[1], 'tick', 0, lineNum);
      const key = parts[2];

      if (!isValidIdentifier(key)) {
        throw new Error(`error: line ${lineNum}: invalid key ${key}`);
      }

      if (tick < lastTick) {
        throw new Error(`error: line ${lineNum}: tick ${tick} is before tick ${lastTick}`);
      }
      lastTick = tick;

      events.push({ tick, key });
    } else {
      throw new Error(`error: line ${lineNum}: unknown directive ${directive}`);
    }
  }

  return { events, policies, routes };
}

// Find the matching route for a key
function findRoute(key, routes) {
  let bestRoute = null;
  let bestPrefixLen = -1;

  for (const route of routes) {
    if (key.startsWith(route.prefix) && route.prefix.length > bestPrefixLen) {
      bestRoute = route;
      bestPrefixLen = route.prefix.length;
    }
  }

  return bestRoute;
}

// Get or create policy state for a key
function getPolicyState(policyStates, policyName, key, policies) {
  const policyMap = policyStates.get(policyName);

  if (!policyMap.has(key)) {
    const policy = policies[policyName];
    let state;

    if (policy.type === 'bucket') {
      state = new BucketState(policy.capacity, policy.refill, policy.per);
    } else {
      state = new WindowState(policy.limit, policy.span);
    }

    policyMap.set(key, state);
  }

  return policyMap.get(key);
}

// Main execution
function main() {
  const mode = process.argv[2];

  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n');
    process.exit(2);
  }

  try {
    const input = readStdin();
    const { events, policies, routes } = parse(input);

    // Initialize policy state maps
    const policyStates = new Map();
    for (const policyName of Object.keys(policies)) {
      policyStates.set(policyName, new Map());
    }

    // Track event results
    const keyStats = new Map(); // key -> { allowed, denied }

    if (mode === 'replay') {
      // Process each event and output immediately
      for (const { tick, key } of events) {
        const route = findRoute(key, routes);

        if (!keyStats.has(key)) {
          keyStats.set(key, { allowed: 0, denied: 0 });
        }

        if (!route) {
          // No route matches, always allow
          console.log(`${tick} ${key} allow`);
          keyStats.get(key).allowed++;
        } else {
          // Check all policies on the route
          let allowed = true;
          let denyingPolicy = null;

          // First advance all policies and check if all allow
          const states = [];
          for (const policyName of route.policyNames) {
            const state = getPolicyState(policyStates, policyName, key, policies);
            state.advance(tick);
            states.push({ policyName, state });
          }

          // Check if all allow
          for (const { policyName, state } of states) {
            if (!state.check()) {
              allowed = false;
              denyingPolicy = policyName;
              break;
            }
          }

          if (allowed) {
            // Record in all policies
            for (const { policyName, state } of states) {
              state.record(tick);
            }
            console.log(`${tick} ${key} allow`);
            keyStats.get(key).allowed++;
          } else {
            console.log(`${tick} ${key} deny ${denyingPolicy}`);
            keyStats.get(key).denied++;
          }
        }
      }
    } else {
      // summary mode - process all events without output, then summarize
      for (const { tick, key } of events) {
        const route = findRoute(key, routes);

        if (!keyStats.has(key)) {
          keyStats.set(key, { allowed: 0, denied: 0 });
        }

        if (!route) {
          keyStats.get(key).allowed++;
        } else {
          let allowed = true;

          // Advance and check all policies
          const states = [];
          for (const policyName of route.policyNames) {
            const state = getPolicyState(policyStates, policyName, key, policies);
            state.advance(tick);
            states.push({ policyName, state });
          }

          for (const { policyName, state } of states) {
            if (!state.check()) {
              allowed = false;
              break;
            }
          }

          if (allowed) {
            for (const { policyName, state } of states) {
              state.record(tick);
            }
            keyStats.get(key).allowed++;
          } else {
            keyStats.get(key).denied++;
          }
        }
      }

      // Output summary
      const sortedKeys = Array.from(keyStats.keys()).sort();
      let totalAllowed = 0;
      let totalDenied = 0;

      for (const key of sortedKeys) {
        const stats = keyStats.get(key);
        console.log(`${key} allowed=${stats.allowed} denied=${stats.denied}`);
        totalAllowed += stats.allowed;
        totalDenied += stats.denied;
      }

      console.log(`total allowed=${totalAllowed} denied=${totalDenied}`);
    }

    process.exit(0);
  } catch (e) {
    process.stderr.write(e.message + '\n');
    process.exit(2);
  }
}

main();

