 * Simulation of the declared policies over the event log.
 *
 * Token amounts are kept as exact rationals: a bucket stores an integer
 * numerator over the fixed denominator `per`, so fractional refills never
 * lose precision.
 */

class Bucket {
  constructor(def, tick) {
    this.capacity = def.capacity;
    this.refill = def.refill;
    this.per = def.per;
    this.max = def.capacity * def.per;
    this.num = this.max; // starts full
    this.last = tick;
  }

  advance(tick) {
    const elapsed = tick - this.last;
    if (elapsed > 0n) {
      this.num += this.refill * elapsed;
      if (this.num > this.max) this.num = this.max;
    }
    this.last = tick;
  }

  allows() {
    return this.num >= this.per;
  }

  record() {
    this.num -= this.per;
  }
}

class Window {
  constructor(def) {
    this.limit = def.limit;
    this.span = def.span;
    this.ticks = [];
    this.head = 0;
  }

  advance(tick) {
    const cutoff = tick - this.span;
    while (this.head < this.ticks.length && this.ticks[this.head] <= cutoff) {
      this.head++;
    }
    if (this.head > 64 && this.head * 2 >= this.ticks.length) {
      this.ticks = this.ticks.slice(this.head);
      this.head = 0;
    }
  }

  allows() {
    return BigInt(this.ticks.length - this.head) < this.limit;
  }

  record(tick) {
    this.ticks.push(tick);
  }
}

function routeFor(key, routes) {
  let best = null;
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) best = route;
    }
  }
  return best;
}

export function simulate({ policies, routes, events }, mode) {
  const states = new Map(); // policy name -> Map(key -> state)
  for (const name of policies.keys()) states.set(name, new Map());

  const stateFor = (name, key, tick) => {
    const perKey = states.get(name);
    let state = perKey.get(key);
    if (state === undefined) {
      const def = policies.get(name);
      state = def.type === 'bucket' ? new Bucket(def, tick) : new Window(def);
      perKey.set(key, state);
    }
    return state;
  };

  const out = [];
  const stats = new Map(); // key -> { allowed, denied }
  let totalAllowed = 0;
  let totalDenied = 0;

  for (const { tick, key } of events) {
    let stat = stats.get(key);
    if (stat === undefined) {
      stat = { allowed: 0, denied: 0 };
      stats.set(key, stat);
    }

    const route = routeFor(key, routes);
    let denier = null;
    const chain = [];

    if (route !== null) {
      for (const name of route.policyNames) {
        const state = stateFor(name, key, tick);
        state.advance(tick);
        chain.push({ name, state });
      }
      for (const entry of chain) {
        if (!entry.state.allows()) {
          denier = entry.name;
          break;
        }
      }
    }

    if (denier === null) {
      for (const entry of chain) entry.state.record(tick);
      stat.allowed++;
      totalAllowed++;
      if (mode === 'replay') out.push(`${tick} ${key} allow\n`);
    } else {
      stat.denied++;
      totalDenied++;
      if (mode === 'replay') out.push(`${tick} ${key} deny ${denier}\n`);
    }
  }

  if (mode === 'summary') {
    const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    for (const key of keys) {
      const stat = stats.get(key);
      out.push(`${key} allowed=${stat.allowed} denied=${stat.denied}\n`);
    }
    out.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`);
  }

  return out.join('');
}
"}

